import React from 'react';

function ListContacts() {
    const items = [
        {
            link: 'mailto:patel24111@gmail.com',
            icon: 'fas fa-envelope fa-lg'
        },
        {
            link: 'https://github.com/akshayrpatel',
            icon: 'fab fa-github fa-lg'
        },
        {
            link: 'https://www.linkedin.com/in/akshayrpatel/',
            icon: 'fab fa-linkedin fa-lg'
        }
    ]

    const listItems = items.map((item, index) => {
        return( 
            <li key={index}>
                <a href={item.link}>
                    <span className="icon has-text-white">
                        <i className={item.icon}></i>
                    </span>
                </a>
            </li>
        )
    })

    return(
        <ul>
            {listItems}
        </ul>
    )
}

const Contact = () => {
    return (
        <div id="contact" className="Contact has-background-grey-dark">
          <div className="container">
            <div className="column">
              <nav className="breadcrumb is-centered has-bullet-separator" aria-label="breadcrumbs">
                  <ListContacts/>
              </nav>
            </div>
          </div>
        </div>
    );
};

export default Contact;