import React from 'react';

const About = () => {
    return (
        <div id="about" className="About">
          <div className="column">
            <div className="column is-size-3 has-text-white has-text-centered has-text-weight-bold">
              <h1 className="title has-text-white">ABOUT</h1>
            </div>
            <div className="column has-text-white">
              <article className="tile is-child box">
                <div className="content">
                  <p className="is-size-6-mobile is-size-6-tablet is-size-5-desktop">Hi, I am <strong>Akshay</strong>. Currently, I am a studying Computer Science at York University - Toronto, ON.
                  Technology is something that I have been passionate about since high school. Smartphones were just starting to evolve back then and
                  one of my friends had an HTC. He showed me a bunch of cool apps to which I simply reacted - WOW! 
                  Soon after, he showed me a chemical balancer app on his phone that he built applying concepts we learned at school. 
                  It was that moment when I decided to pursue a career in technology.
                  </p>
                </div>
                <div className="content">
                  <p className="is-size-6-mobile is-size-6-tablet is-size-5-desktop">
                  After finishing high school where I had the opportunity to take some computer science courses, I enrolled in Computer Engineering at
                  University of Mumbai - K.J. Somaiya College of Engineering. Unfortunately, I had to drop out as I was eligible for the PR status in Canada.
                  From the notion that North America provides the opportunity of success to anyone from any background, and having some relatives in NA, I chose to come to Canada. 
                  </p>
                </div>
              </article>
            </div>
          </div>
        </div>
    );
};

export default About;