import React, { Component } from 'react';
import Navbar from './Navbar'

class Home extends Component {

	handleOnClick(target)
	{
			// get element and scroll the element into view
			var el = document.getElementById(target.name)
			el.scrollIntoView({behavior: "smooth", block: "start", inline: "nearest"})
	}

	componentDidMount() {
		// Get all "navbar-burger" elements
		const $navbarBurgers = Array.prototype.slice.call(document.querySelectorAll('.navbar-burger'), 0);
		
		// Check if there are any navbar burgers
		if ($navbarBurgers.length > 0) {

				// Add a click event on each of them
				$navbarBurgers.forEach( el => {
						el.addEventListener('click', () => {
		
						// Get the target from the "data-target" attribute
						const target = el.dataset.target;
						const $target = document.getElementById(target);
		
						// Toggle the "is-active" class on both the "navbar-burger" and the "navbar-menu"
						el.classList.toggle('is-active');
						$target.classList.toggle('is-active');
						});
				});
		}

		this.closePageLoader()
	}

	closePageLoader() {
		setTimeout(function(){ 
			var loader = document.querySelector('div#home.Home div.pageloader')
			loader.classList.toggle('is-active')
		}, 2000);
	}

	render() {
		return (
			<div id="home" className="Home">
				<div className="pageloader is-active is-black"></div>
				<Navbar/>

				<section className="hero is-fullheight">
					<div className="hero-body">						
						<div className="container has-text-centered">
							{/* <figure style={centered} className="image">
								<img alt="" src={bulma} style={imgStyle}/>
							</figure> */}

							<div className="column">
								<p className="title is-size-3-mobile is-size-2-tablet is-size-1-desktop has-text-weight-bold">
									"A good programmer is someone who always looks both ways before crossing a one-way street."
								</p>
							</div>
							<div className="column">
								<p className="title is-size-5-mobile is-size-4-tablet is-size-3-desktop has-text-weight-light is-italic has-text-right">
									- Doug Linder
								</p>
							</div>

						</div>
					</div>
					<div className="column has-text-centered">
						<a href="#About" name="about" className="button is-black" onClick={(e) => this.handleOnClick(e.target)}>
								FIND OUT MORE
						</a>
					</div>
				</section>
			</div>
		);
	}
}

export default Home;