import React, { Component } from 'react';

class Navbar extends Component {

	constructor() {
		super()
		this.handleOnClick = this.handleOnClick.bind(this)
	}

	handleOnClick(target) {
		// get element and scroll the element into view
		var el = document.getElementById(target.text.toLowerCase())
		el.scrollIntoView({behavior: "smooth", block: "start", inline: "nearest"})

		// close the navbar list
		var navMenu = document.getElementById('navMenu')
		var activeMenuItem = document.getElementsByClassName("navbar-burger burger")
		navMenu.classList.remove("is-active")
		activeMenuItem[0].classList.remove("is-active")
	}

	render() {
		return(
			<nav className="navbar is-fixed-top">
				<div className="container">
					<div className="navbar-brand">
						<a href="#Home" className="navbar-item has-text-white has-text-weight-bold is-size-6-mobile is-size-5-tablet is-size-4-desktop">
							Akshay Patel
						</a>
						<span className="navbar-burger burger" data-target="navMenu">
							<span></span>
							<span></span>
							<span></span>
						</span>
					</div>
					<div id="navMenu" className="navbar-menu navMenuBackground">
						<div className="navbar-end">
							<a className="navbar-item has-text-white" href="#Home" onClick={(e) => this.handleOnClick(e.target)}>
								Home
							</a>
							<a className="navbar-item has-text-white" href="#About" onClick={(e) => this.handleOnClick(e.target)}>
								About
							</a>
							<a className="navbar-item has-text-white" href="#Timeline" onClick={(e) => this.handleOnClick(e.target)}>
								Timeline
							</a>
							<a className="navbar-item has-text-white" href="#Projects" onClick={(e) => this.handleOnClick(e.target)}>
								Projects
							</a>
							<a className="navbar-item has-text-white" href="#Skills" onClick={(e) => this.handleOnClick(e.target)}>
								Skills
							</a>
							<a className="navbar-item has-text-white" href="#Contact" onClick={(e) => this.handleOnClick(e.target)}>
								Contact
							</a>
						</div>
					</div>
				</div>
			</nav> 
		)
	}
}

export default Navbar;