import React, { Component } from 'react';

class Skills extends Component {

  constructor()
  {
    super();

    this.state = {
      'programming': ['C', 'C++', 'Java', 'JavaScript', 'Python', 'PHP', 'MATLAB', 'SQL'],
      'web': ['HTML5', 'CSS3', 'ReactJS', 'Redux', 'VueJS', 'Vuex', 'Semantic UI', 'Bulma'],
      'other': ['Flask', 'Tomcat', 'NodeJS', 'Derby', 'JDBC', 'XML', 'DITA', 'SOAP', 'REST', 'Handlebars']
    }

    this.listSkills = this.listSkills.bind(this)
  }

  listSkills(skills){
    const skillItems = skills.map((skill)=>{
      return(
        <span class="tag is-medium">{skill}</span>
        // <li>
        //   <a className="subtitle is-size-7-mobile is-size-6-tablet is-size-5-desktop">{skill}</a>
        // </li>
      )
    })

    return skillItems
  }

  render() {
    return (
      <div id="skills" className="Skills">
        <div className="column">
          <div className="column is-size-3 has-text-centered has-text-weight-bold">
            <h1 className="title">SKILLS</h1>
          </div>
        
          <section className="hero">
            <div className="hero-body">
              <div className="columns is-desktop">
                <div className="column">
                  <div class="content has-text-centered">
                    <aside class="menu">
                      <p class="menu-label is-size-7-mobile is-size-6">
                        PROGRAMMING
                      </p>
                      <div class="tags">
                        {this.listSkills(this.state.programming)}
                      </div>
                    </aside>
                  </div>
                </div>
                <div className="column">
                  <div class="content has-text-centered">
                    <aside class="menu">
                      <p class="menu-label is-size-7-mobile is-size-6">
                        WEB TECHNOLOGIES
                      </p>
                      <div class="tags">
                        {this.listSkills(this.state.web)}
                      </div>
                    </aside>
                  </div>
                </div>
                <div className="column">
                  <div class="content has-text-centered">
                    <aside class="menu">
                      <p class="menu-label is-size-7-mobile is-size-6">
                        OTHER
                      </p>
                      <div class="tags">
                        {this.listSkills(this.state.other)}
                      </div>
                    </aside>
                  </div>
                </div>
              </div>
            </div>
          </section>
        </div>
      </div>
    );
  }
}

export default Skills;